{
  "technical_and_design_decisions": [
    "Implement the shell command 'runtime info' in Spring Cloud Data Flow shell by exposing standard REST endpoints on the server and rendering module runtime metrics (host, port, state).",
    "Develop the YARN deployer by implementing the Spring Cloud Deployer SPI for Hadoop YARN using Spring YARN primitives and resource manager interaction.",
    "Port the file source module by wrapping Spring Integration File inbound adapters into Spring Cloud Stream source contracts using Spring Boot autoconfiguration.",
    "Refactor build configuration (Maven/Gradle) to separate SPI deployers into dedicated sub-projects and build artifacts, decoupling the core server runtime from deployer implementations.",
    "Replace XDRuntimeException across Spring XD with appropriate standard JDK or Spring Framework exceptions (such as NestedRuntimeException derivatives).",
    "Update SFTP source module metadata registry configuration to include SFTP in out-of-the-box (OOTB) lists and update repository deployment configs for snapshot publishing."
  ],
  "assumptions": [
    "Development work will be performed by a single developer familiar with Spring Framework, Spring Cloud Data Flow, Spring Cloud Stream, and Hadoop/YARN.",
    "Target environment includes Java 17+ and access to a testing environment with a Hadoop/YARN cluster.",
    "Continuous Integration infrastructure (e.g., Concourse CI or Jenkins) is accessible and configurable.",
    "Maven deployment permissions to repo.spring.io are available for publishing snaphot and release artifacts."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement Runtime Info Shell Command (U1)",
      "activity_description": "Add REST endpoint support for runtime information (host, port, instance metrics) and expose a corresponding shell command in the Spring Cloud Data Flow shell CLI.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Implement YARN Deployer for Spring Cloud Data Flow (U2)",
      "activity_description": "Implement the Spring Cloud Deployer SPI for YARN, managing container lifecycle, stream/batch app execution on Hadoop YARN clusters, and unit/integration testing.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Port File Source Module to Spring Cloud Stream (U3)",
      "activity_description": "Migrate the legacy file source module from Spring XD to the Spring Cloud Stream repository, updating channel bindings, configuration properties, and automated tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Refactor Build Lifecycle for SPI Deployer Isolation (U4)",
      "activity_description": "Restructure build lifecycle scripts and multi-module dependency tree to package deployer SPI implementations independently of the core server/admin artifact.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Remove XDRuntimeException from Spring XD (U5)",
      "activity_description": "Identify and refactor all occurrences of XDRuntimeException, replacing them with specific domain or standard Spring Framework runtime exceptions.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Upgrade and Release GemFire Sink Module (U6)",
      "activity_description": "Update dependencies to the latest GemFire client version, resolve breaking API changes, verify streaming functionality, and prepare module release.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Publish and Register SFTP Source Module OOTB (U7)",
      "activity_description": "Ensure SFTP source module is included in the OOTB module configuration, fix artifact publishing pipeline to spring maven repository, and verify availability.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "CI Pipeline Gaps Resolution (U8)",
      "activity_description": "Resolve remaining CI pipeline issues across Data Flow repositories to enable automated build, test execution, and deployment verification on every commit.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Testing and Integrated Release Verification",
      "activity_description": "Perform end-to-end integration testing across all updated modules, deployers, and shell features to ensure overall compatibility before release.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 35
  }
}

